import json
G=[[0]*30 for _ in range(17)]
# Translate the four objects so their top row matches the color-8 object's top row (row 7).
shapes={
 3:[[(0,c) for c in range(2,7)],[(1,4)],[(2,c) for c in range(3,6)],[(3,c) for c in range(2,7)],[(4,4)]],
 1:[[(0,c) for c in range(9,14)],[(1,11)],[(2,c) for c in range(10,13)],[(3,c) for c in range(9,14)],[(4,11)]],
 4:[[(0,c) for c in range(14,19)],[(1,16)],[(2,c) for c in range(15,18)],[(3,c) for c in range(14,19)],[(4,16)]],
 8:[[(0,c) for c in range(21,26)],[(1,23)],[(2,c) for c in range(22,25)],[(3,c) for c in range(21,26)],[(4,23)]]}
for color, rows in shapes.items():
 for dr, coords in enumerate(rows):
  for c in coords: G[7+dr][c]=color
assert len(G)==17 and all(len(r)==30 for r in G)
print(json.dumps(G,separators=(',',':')))

